// Manchester encoder module
module manchester_encoder #(
    parameter N = 8  // Default width of input data
) (
    input  logic clk_in,          // Clock input
    input  logic rst_in,          // Active high reset input
    input  logic enc_valid_in,        // Input valid signal
    input  logic [N-1:0] enc_data_in, // N-bit input data
    output logic enc_valid_out,       // Output valid signal
    output logic [2*N-1:0] enc_data_out // 2N-bit output encoded data
);

    // Internal register to hold the encoded data


    // Registered encoding, following the rising-edge timing specification
    always_ff @(posedge clk_in or posedge rst_in) begin
        enc_data_out <= '0;
        enc_valid_out <= 1'b0;
        if (enc_valid_in && !rst_in) begin
            for (int i = 0; i < N; i++) begin
                if (enc_data_in[i] == 1'b1) begin
                    enc_data_out[2*i] <= 1'b1;
                    enc_data_out[2*i + 1] <= 1'b0;
                end else begin
                    enc_data_out[2*i] <= 1'b0;
                    enc_data_out[2*i + 1] <= 1'b1;
                end
            end
            enc_valid_out <= 1'b1; // Set the valid signal
        end else begin
            enc_valid_out <= 1'b0; // Clear the valid signal if no valid input
        end
    end

endmodule

module fifo_async #(parameter DATA_WIDTH=32,DEPTH=16)(input w_clk,w_rst,w_inc,input [DATA_WIDTH-1:0] w_data,input r_clk,r_rst,r_inc,output w_full,r_empty,output wire [DATA_WIDTH-1:0] r_data);
localparam AW=$clog2(DEPTH);
reg [DATA_WIDTH-1:0] mem[0:DEPTH-1];
reg [AW:0] wb,rb,wg,rg,rs1,rs2,ws1,ws2;
wire [AW:0] wn=wb+{{AW{1'b0}},(w_inc&&!w_full)};
wire [AW:0] rn=rb+{{AW{1'b0}},(r_inc&&!r_empty)};
wire [AW:0] rbin;
genvar j;generate for(j=0;j<=AW;j=j+1)begin assign rbin[j]=^(rs2>>j);end endgenerate
assign w_full=(wb[AW]!=rbin[AW]) && (wb[AW-1:0]==rbin[AW-1:0]);
assign r_empty=rg==ws2;
assign r_data=mem[rb[AW-1:0]];
always @(posedge w_clk or posedge w_rst)if(w_rst)begin wb<=0;wg<=0;rs1<=0;rs2<=0;end
else begin rs1<=rg;rs2<=rs1;wb<=wn;wg<=(wn>>1)^wn;if(w_inc&&!w_full)mem[wb[AW-1:0]]<=w_data;end
always @(posedge r_clk or posedge r_rst)if(r_rst)begin rb<=0;rg<=0;ws1<=0;ws2<=0;end
else begin ws1<=wg;ws2<=ws1;rb<=rn;rg<=(rn>>1)^rn;end
endmodule

module axis_rgb2ycbcr #(parameter PIXEL_WIDTH=16,FIFO_DEPTH=16)(input aclk,aresetn,input [15:0] s_axis_tdata,input s_axis_tvalid,output s_axis_tready,input s_axis_tlast,s_axis_tuser,output [15:0] m_axis_tdata,output m_axis_tvalid,input m_axis_tready,output m_axis_tlast,m_axis_tuser);
